 public void PreviewNamesScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;LeaveLan();ApplyTheme(true,true);ApplyMode(false);lanName.Text="鱼子";ShowPage("lan");Render(Path.Combine(folder,"146-player-name-lobby-normal.png"));ApplyMode(true);Render(Path.Combine(folder,"147-player-name-lobby-minimal.png"));Check(Width==392&&Height==300&&lanName.ActualHeight>0,"Name field visible in fixed minimal lobby");ApplyMode(false);VerifyNamesTcp(folder);localTest=true;myName.Text="测试甲";opponentName.Text="测试乙";ShowPage("lobby");Render(Path.Combine(folder,"149-player-names-local-test.png"));StartConfiguredMatch();Check(match.Players[0].DisplayName=="测试甲"&&match.Players[1].DisplayName=="测试乙","Local test names bound before initial draw");match=null;localTest=false;File.WriteAllText(Path.Combine(folder,"player-name-verification.txt"),"PASS: "+(checks-before)+" checks; compact lobby name fields, real loopback TCP, named shared history, unchanged minimal hero and local test naming.");}
 void VerifyNamesTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);guest.SetFullEffects(false);try{
  lanName.Text="  鱼子  ";guest.lanName.Text="纸鱼";lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Named peers connect");Check(match.PlayerLabel(0)=="鱼子"&&match.PlayerLabel(1)=="纸鱼"&&guest.match.PlayerLabel(0)=="鱼子"&&guest.match.PlayerLabel(1)=="纸鱼","Hello handshake sends own name and snapshot synchronizes both");Check(!lanName.IsEnabled&&!guest.lanName.IsEnabled,"Names locked once room is created or joined");Check(match.Log.SequenceEqual(guest.match.Log)&&match.Log[0].Contains("鱼子")&&match.Log[0].Contains("纸鱼"),"Opening shared history has both names");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Named host mulligan");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Named opening done");var g=lanAuthority.Game;g.Players[0].Hand.Clear();g.Players[0].Mana=10;int fire=Inject(g,"CS2_029");PublishLan();BeginCard(fire);ClickMatchTarget(new MatchTarget(1));PumpLan(()=>guest.match.Players[1].Health==24,"Named attack target synchronized");Check(g.Log.Any(x=>x.StartsWith("鱼子 · 使用")&&x.Contains("纸鱼 英雄"))&&guest.match.Log.SequenceEqual(g.Log),"Names recorded in actual shared action log");Check(HeroStatusLabel(0,true).StartsWith("鱼子\n")&&HeroStatusLabel(1,false).StartsWith("纸鱼\n"),"Normal hero name and vital stats on separate lines");Render(Path.Combine(folder,"148-player-names-match-codex.png"));guest.ApplyMode(true);Check(guest.HeroStatusLabel(1,true)=="24"&&guest.Width==392&&guest.Height==300,"Minimal hero still displays only health");lanName.Text="临时改字";Check(g.PlayerLabel(0)=="鱼子","Input field edits cannot rename an ongoing match");
 }finally{guest.LeaveLan();Check(guest.lanName.IsEnabled,"Leaving unlocks name for next match");guest.Close();LeaveLan();Check(lanName.IsEnabled,"Host leaving unlocks name field");}}
